 async function redeemCoupon(e:FormEvent){e.preventDefault();if(!supabase||!couponCode.trim())return;setCouponBusy(true);try{const {data,error}=await supabase.functions.invoke('quiz-api',{body:{action:'coupon',code:couponCode.trim()}});if(error)throw error;if(data?.error)throw new Error(data.error);setCouponCode('');notify('Coupon valido: aggiunti '+data.credits_added+' quiz.');void refreshWallet()}catch(err){notify(err instanceof Error?err.message:'Coupon non valido.')}finally{setCouponBusy(false)}}
